#nullable enable // autogenerated

using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.nightmareRedFilter)]
    public class NightmareRedFilterBuff : BuffDefinition
    {
        public NightmareRedFilterBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(ColorModifier.Multiply(LogicAreaProps.BACKGROUND_LIGHT, new Color(1f, 0.5f, 0.5f)));
        }
    }
}
